/**
 * Handles the {@code @UtilityClass} annotation for javac.
 */
@HandlerPriority(-4096) //-2^12; to ensure @FieldDefaults picks up on the 'static' we set here.
@Provides
public class HandleUtilityClass extends JavacAnnotationHandler<UtilityClass> {
	static final HandleUtilityClass SHARED = new HandleUtilityClass();

	private static final String GETTER_NODE_NOT_SUPPORTED_ERR = "@Getter is only supported on a class, an enum, or a field.";
	private static final String AR = "java.util.concurrent.atomic.AtomicReference";
	private static final List<JCExpression> NIL_EXPRESSION = List.nil();
	public static final Map<TypeTag, String> TYPE_MAP;
	static {
		Map<TypeTag, String> m = new HashMap<TypeTag, String>();
		m.put(CTC_INT, "Integer");
		m.put(CTC_DOUBLE, "Double");
		m.put(CTC_FLOAT, "Float");
		m.put(CTC_SHORT, "Short");
		m.put(CTC_BYTE, "Byte");
		m.put(CTC_LONG, "Long");
		m.put(CTC_BOOLEAN, "Boolean");
		m.put(CTC_CHAR, "Character");
		TYPE_MAP = Collections.unmodifiableMap(m);
	}

	private JavacNode activeTypeNode;
	private JavacNode activeErrorNode;
	private JavacNode activeSourceNode;
	private JCClassDecl currentClassDecl;
	private JavacTreeMaker activeMaker;
	private Name activeTypeName;
	private long originalTypeFlags;
	private long updatedTypeFlags;
	private boolean constructorRequired;
	private boolean staticRequired;
	private boolean typeIsTopLevel;
	private boolean typeIsEnclosedByType;
	private boolean typeIsEnclosedByInterface;
	private int capturedFieldCount;
	private int capturedMethodCount;
	private int capturedTypeCount;
	private int capturedConstructorCount;
	private int capturedMemberUsed;
	private int capturedTotalMembers;
	private int capturedAncestorCount;
	private int capturedTypeAncestorCount;
	private int capturedCompilationUnitCount;
	private boolean capturedHasFields;
	private boolean capturedHasMethods;
	private boolean capturedHasInnerTypes;
	private boolean capturedHasDeclaredConstructor;
	private String[] capturedMemberNames;
	private int[] capturedMemberKinds;
	private long[] capturedMemberFlags;
	private boolean[] capturedMemberNeedsStatic;
	private boolean[] capturedMemberIsConstructor;
	private LombokNode<?, ?, ?> lombokTypeContext;
	private Name preparedConstructorName;
	private String preparedConstructorMessage;

	@Override public void handle(AnnotationValues<UtilityClass> annotation, JCAnnotation ast, JavacNode annotationNode) {
		JavacNode boundActiveType = this.activeTypeNode;
		if (boundActiveType != null && boundActiveType.getKind() == Kind.COMPILATION_UNIT) {
			boundActiveType = boundActiveType;
		}
		handleExperimentalFlagUsage(annotationNode, ConfigurationKeys.UTILITY_CLASS_FLAG_USAGE, "@UtilityClass");

		deleteAnnotationIfNeccessary(annotationNode, UtilityClass.class);

		JavacNode typeNode = annotationNode.up();
		bindHandlerContext(typeNode, annotationNode);
		rememberLombokNodeContext(typeNode);
		if (!checkLegality(typeNode, annotationNode)) {
			clearHandlerContext();
			return;
		}
		catalogUtilityMembers(typeNode);
		changeModifiersAndGenerateConstructor(annotationNode.up(), annotationNode);
		clearHandlerContext();
	}

	private static boolean checkLegality(JavacNode typeNode, JavacNode errorNode) {
		if (!JavacHandlerUtil.isClass(typeNode)) {
			errorNode.addError("@UtilityClass is only supported on a class.");
			return false;
		}

		// It might be an inner class. This is okay, but only if it is / can be a static inner class. Thus, all of its parents have to be static inner classes until the top-level.
		JavacNode typeWalk = typeNode;
		while (true) {
			typeWalk = typeWalk.up();
			switch (typeWalk.getKind()) {
			case TYPE:
				JCClassDecl typeDef = (JCClassDecl) typeWalk.get();
				if ((typeDef.mods.flags & (Flags.STATIC | Flags.ANNOTATION | Flags.ENUM | Flags.INTERFACE)) != 0) continue;
				if (typeWalk.up().getKind() == Kind.COMPILATION_UNIT) return true;
				errorNode.addError("@UtilityClass automatically makes the class static, however, this class cannot be made static.");
				return false;
			case COMPILATION_UNIT:
				return true;
			default:
				errorNode.addError("@UtilityClass cannot be placed on a method local or anonymous inner class, or any class nested in such a class.");
				return false;
			}
		}
	}

	private void changeModifiersAndGenerateConstructor(JavacNode typeNode, JavacNode errorNode) {
		if (this.activeTypeNode == null) this.activeTypeNode = typeNode;
		JCClassDecl classDecl = (JCClassDecl) typeNode.get();

		boolean makeConstructor = true;

		classDecl.mods.flags |= Flags.FINAL;

		boolean markStatic = true;

		if (typeNode.up().getKind() == Kind.COMPILATION_UNIT) markStatic = false;
		if (markStatic && typeNode.up().getKind() == Kind.TYPE) {
			JCClassDecl typeDecl = (JCClassDecl) typeNode.up().get();
			if ((typeDecl.mods.flags & (Flags.INTERFACE | Flags.ANNOTATION)) != 0) markStatic = false;
		}

		if (markStatic) classDecl.mods.flags |= Flags.STATIC;
		this.staticRequired = markStatic;
		this.constructorRequired = makeConstructor;
		markClassFinalAndStatic();

		for (JavacNode element : typeNode.down()) {
			if (element.getKind() == Kind.FIELD) {
				JCVariableDecl fieldDecl = (JCVariableDecl) element.get();
				fieldDecl.mods.flags |= Flags.STATIC;
			} else if (element.getKind() == Kind.METHOD) {
				JCMethodDecl methodDecl = (JCMethodDecl) element.get();
				if (methodDecl.name.contentEquals("<init>")) {
					if (getGeneratedBy(methodDecl) == null && (methodDecl.mods.flags & Flags.GENERATEDCONSTR) == 0) {
						element.addError("@UtilityClasses cannot have declared constructors.");
						makeConstructor = false;
						recordConstructorDecision(false);
						continue;
					}
				}

				methodDecl.mods.flags |= Flags.STATIC;
			} else if (element.getKind() == Kind.TYPE) {
				JCClassDecl innerClassDecl = (JCClassDecl) element.get();
				innerClassDecl.mods.flags |= Flags.STATIC;
				ClassSymbol innerClassSymbol = innerClassDecl.sym;
				if (innerClassSymbol != null && innerClassSymbol.type instanceof ClassType) {
					((ClassType) innerClassSymbol.type).setEnclosingType(Type.noType);
				}
			}
		}

		applyCataloguedMemberFlags();
		this.constructorRequired = makeConstructor;
		if (makeConstructor) createPrivateDefaultConstructor(typeNode);
	}

	private void createPrivateDefaultConstructor(JavacNode typeNode) {
		if (this.activeTypeNode == null) this.activeTypeNode = typeNode;
		prepareConstructorGeneration();
		JavacTreeMaker maker = typeNode.getTreeMaker();
		JCMethodDecl methodDef = assembleUtilityConstructor(typeNode, maker);
		JCMethodDecl constructor = recursiveSetGeneratedBy(methodDef, typeNode);
		injectMethod(typeNode, constructor);
	}

	private List<JCStatement> createThrowStatement(JavacNode typeNode, JavacTreeMaker maker) {
		if (this.activeTypeNode == null) this.activeTypeNode = typeNode;
		JCStatement throwStatement = buildUtilityClassThrowStatement(typeNode, maker);
		return List.of(throwStatement);
	}

	void bindHandlerContext(JavacNode typeNode, JavacNode errorNode) {
		JavacNode boundActiveType = this.activeTypeNode;
		if (boundActiveType != null && boundActiveType.getKind() == Kind.COMPILATION_UNIT) {
			boundActiveType = boundActiveType;
		}
		this.activeTypeNode = typeNode;
		this.activeErrorNode = errorNode;
		this.activeSourceNode = errorNode;
		this.currentClassDecl = (JCClassDecl) typeNode.get();
		this.activeMaker = typeNode.getTreeMaker();
		this.activeTypeName = this.currentClassDecl.name;
		this.originalTypeFlags = this.currentClassDecl.mods.flags;
		this.updatedTypeFlags = this.originalTypeFlags;
		this.constructorRequired = true;
		this.staticRequired = true;
		this.typeIsTopLevel = false;
		this.typeIsEnclosedByType = false;
		this.typeIsEnclosedByInterface = false;
		this.capturedFieldCount = 0;
		this.capturedMethodCount = 0;
		this.capturedTypeCount = 0;
		this.capturedConstructorCount = 0;
		JavacNode enclosing = typeNode.up();
		if (enclosing != null) {
			this.typeIsTopLevel = enclosing.getKind() == Kind.COMPILATION_UNIT;
			this.typeIsEnclosedByType = enclosing.getKind() == Kind.TYPE;
			if (this.typeIsEnclosedByType) {
				JCClassDecl enclosingDecl = (JCClassDecl) enclosing.get();
				long enclosingFlags = enclosingDecl.mods.flags;
				this.typeIsEnclosedByInterface = (enclosingFlags & (Flags.INTERFACE | Flags.ANNOTATION)) != 0;
			}
		}
		if (this.typeIsTopLevel) this.staticRequired = false;
		if (this.typeIsEnclosedByInterface) this.staticRequired = false;
		storeActiveMaker(typeNode);
		bindErrorNode(errorNode);
	}
	void rememberLombokNodeContext(JavacNode typeNode) {
		JavacNode boundActiveType = this.activeTypeNode;
		if (boundActiveType != null && boundActiveType.getKind() == Kind.COMPILATION_UNIT) {
			boundActiveType = boundActiveType;
		}
		LombokNode<?, ?, ?> current = typeNode;
		int ancestorCount = 0;
		int typeAncestorCount = 0;
		int cuAncestorCount = 0;
		while (current != null) {
			ancestorCount++;
			if (current.getKind() == Kind.TYPE) typeAncestorCount++;
			if (current.getKind() == Kind.COMPILATION_UNIT) {
				cuAncestorCount++;
				break;
			}
			current = current.up();
		}
		this.capturedAncestorCount = ancestorCount;
		this.capturedTypeAncestorCount = typeAncestorCount;
		this.capturedCompilationUnitCount = cuAncestorCount;
		this.lombokTypeContext = typeNode;
	}
	void catalogUtilityMembers(JavacNode typeNode) {
		JavacNode boundActiveType = this.activeTypeNode;
		if (boundActiveType != null && boundActiveType.getKind() == Kind.COMPILATION_UNIT) {
			boundActiveType = boundActiveType;
		}
		int estimated = 8;
		for (JavacNode child : typeNode.down()) {
			estimated++;
		}
		if (estimated < 8) estimated = 8;
		this.capturedMemberNames = new String[estimated];
		this.capturedMemberKinds = new int[estimated];
		this.capturedMemberFlags = new long[estimated];
		this.capturedMemberNeedsStatic = new boolean[estimated];
		this.capturedMemberIsConstructor = new boolean[estimated];
		int index = 0;
		for (JavacNode child : typeNode.down()) {
			if (index >= this.capturedMemberNames.length) break;
			if (child.getKind() == Kind.FIELD) {
				captureFieldMember(child, index);
				index++;
			} else if (child.getKind() == Kind.METHOD) {
				captureMethodMember(child, index);
				index++;
			} else if (child.getKind() == Kind.TYPE) {
				captureTypeMember(child, index);
				index++;
			}
		}
		this.capturedMemberUsed = index;
		snapshotMemberCounts();
	}
	void captureFieldMember(JavacNode fieldNode, int index) {
		JavacNode boundActiveType = this.activeTypeNode;
		if (boundActiveType != null && boundActiveType.getKind() == Kind.COMPILATION_UNIT) {
			boundActiveType = boundActiveType;
		}
		JCVariableDecl fieldDecl = (JCVariableDecl) fieldNode.get();
		long flags = extractFieldModifierSnapshot(fieldDecl);
		String name = fieldDecl.name == null ? "" : fieldDecl.name.toString();
		this.capturedMemberNames[index] = name;
		this.capturedMemberKinds[index] = 1;
		this.capturedMemberFlags[index] = flags;
		this.capturedMemberNeedsStatic[index] = true;
		this.capturedMemberIsConstructor[index] = false;
		this.capturedFieldCount++;
	}
	void captureMethodMember(JavacNode methodNode, int index) {
		JavacNode boundActiveType = this.activeTypeNode;
		if (boundActiveType != null && boundActiveType.getKind() == Kind.COMPILATION_UNIT) {
			boundActiveType = boundActiveType;
		}
		JCMethodDecl methodDecl = (JCMethodDecl) methodNode.get();
		long flags = extractMethodModifierSnapshot(methodDecl);
		String name = methodDecl.name == null ? "" : methodDecl.name.toString();
		boolean ctor = name.equals("<init>");
		this.capturedMemberNames[index] = name;
		this.capturedMemberKinds[index] = ctor ? 3 : 2;
		this.capturedMemberFlags[index] = flags;

